package connections

import (
	"context"
	"golang.org/x/crypto/ssh"
	"net"
	"os"
	"path/filepath"
	"strconv"
	"testing"
	"time"
)

// SQL fixtures are generated by the application's tableData.ts helpers. The
// test may only connect to the explicitly provisioned local integration server.
func TestTableWorkflowsIntegration(t *testing.T) {
	directory := os.Getenv("BAJIU_TABLE_WORKFLOW_SQL_DIR")
	if directory == "" {
		t.Skip("generated table workflow fixtures required")
	}
	if os.Getenv("BAJIU_MYSQL_TEST_ADDR") != "127.0.0.1:33179" {
		t.Fatal("dedicated local test server required")
	}
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()
	input := Input{Profile: Profile{Host: "127.0.0.1", Port: 33179, Username: "root", Timeout: 10, TLSMode: "disabled"}}
	for _, transport := range []string{"direct", "ssh"} {
		t.Run(transport, func(t *testing.T) {
			in := input
			if transport == "ssh" {
				address, signer, _ := testSSHServer(t, "127.0.0.1:33179")
				host, port, err := net.SplitHostPort(address)
				if err != nil {
					t.Fatal(err)
				}
				in.TunnelMode = "ssh"
				in.SSHHost = host
				in.SSHPort, err = strconv.Atoi(port)
				if err != nil {
					t.Fatal(err)
				}
				in.SSHUsername = "qa"
				in.SSHAuth = "password"
				in.SSHPassword = "ssh-test-only"
				in.SSHFingerprint = ssh.FingerprintSHA256(signer.PublicKey())
			}
			db, err := (MySQLDialer{}).Open(ctx, in, "")
			if err != nil {
				t.Fatal(err)
			}
			defer db.Close()
			admin := db.(adminDatabase)
			name := "bajiu_table_workflows_qa_" + transport
			call := func(schema string, request AdminRequest) AdminResult {
				t.Helper()
				result, err := admin.Admin(ctx, schema, request)
				if err != nil || result.Error != "" {
					t.Fatalf("%s: %v %s", request.Operation, err, result.Error)
				}
				return result
			}
			call("", AdminRequest{Operation: "query", SQL: "DROP DATABASE IF EXISTS " + quoteIdentifier(name)})
			call("", AdminRequest{Operation: "create", Name: name, Charset: "utf8mb4", Collation: "utf8mb4_general_ci"})
			defer admin.Admin(context.Background(), name, AdminRequest{Operation: "drop", Name: name})
			for _, file := range []string{"create.sql", "import.sql", "generate.sql"} {
				data, err := os.ReadFile(filepath.Join(directory, file))
				if err != nil {
					t.Fatal(err)
				}
				call(name, AdminRequest{Operation: "query", SQL: string(data)})
			}
			data := call(name, AdminRequest{Operation: "query", SQL: "SELECT name,amount FROM csv_data ORDER BY id"})
			rows := data.Results[0].Rows
			if len(rows) != 4 || *rows[0][0] != "O'Brien, 演示\nnext" || *rows[0][1] != "9007199254740993.125" || rows[1][1] != nil || *rows[2][0] != "name_7" || *rows[3][0] != "name_8" {
				t.Fatalf("table workflow data mismatch: %#v", rows)
			}
			metadata := call(name, AdminRequest{Operation: "query", SQL: "SHOW FULL COLUMNS FROM csv_data"})
			if len(metadata.Results[0].Rows) != 4 || *metadata.Results[0].Rows[0][6] != "auto_increment" || *metadata.Results[0].Rows[3][6] != "VIRTUAL GENERATED" {
				t.Fatal("missing auto/generated column metadata")
			}
		})
	}
}
